# - snap_fwd uses overhang D, input_rev uses overhang D

my %primer_overhangs = (
    'input_fwd' => 'AAAA',
    'input_rev' => 'TTTT',
    'egfp_fwd' => 'CCCC',
    'egfp_rev' => 'AAAA',
    'flag_fwd' => 'GGGG',
    'flag_rev' => 'CCCC',
    'snap_fwd' => 'TTTT',
    'snap_rev' => 'GGGG',
);

# Design primers for each template
my @templates = ('input', 'egfp', 'flag', 'snap');
my @primers;

foreach my $template (@templates) {
    my $seq = $sequences{$template};
    next unless $seq;

    print "Designing primers for $template (length: " . length($seq) . ")\n";

    # Forward primer
    my $fwd_overhang = $primer_overhangs{"${template}_fwd"};
    my $fwd_primer;
    my $fwd_tm;
    my $fwd_found = 0;

    for my $len (20..35) {
        my $template_region = substr($seq, 0, $len);
        my $tm = calc_tm($template_region);

        if (defined $tm && $tm >= 58 && $tm <= 72) {
            $fwd_primer = "GGTCTC${fwd_overhang}${template_region}";
            $fwd_tm = $tm;
            $fwd_found = 1;
            print "  FWD: len=$len, Tm=$tm\n";
            last;
        }
    }

    # Reverse primer - must pair within 5°C of forward
    my $rev_overhang = $primer_overhangs{"${template}_rev"};
    my $rev_primer;
    my $rev_tm;
    my $rev_found = 0;

    if ($fwd_found) {
        for my $len (20..35) {
            my $template_region = substr($seq, -$len);
            my $template_region_rc = rev_comp($template_region);
            my $tm = calc_tm($template_region_rc);

            if (defined $tm && $tm >= 58 && $tm <= 72 && abs($fwd_tm - $tm) <= 5) {
                $rev_primer = "GGTCTC${rev_overhang}${template_region_rc}";
                $rev_tm = $tm;
                $rev_found = 1;
                print "  REV: len=$len, Tm=$tm (diff=" . abs($fwd_tm - $tm) . ")\n";
                last;
            }
        }
    }

    if ($fwd_found && $rev_found) {
        push @primers, {
            name => "${template}_fwd",
            seq => $fwd_primer,
            tm => $fwd_tm,
        };
        push @primers, {
            name => "${template}_rev",
            seq => $rev_primer,
            tm => $rev_tm,
        };
        print "  ✓ SUCCESS\n\n";
    } else {
        print "  ✗ FAILED\n\n";
    }
}

# Write output FASTA
