# Function to calculate Tm
sub calc_tm {
    my ($seq) = @_;
    return undef if length($seq) < 2 || length($seq) > 36;
    my $cmd = "oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 '$seq' 2>/dev/null";
    my $result = `$cmd`;
    chomp $result;
    if ($result =~ /(\d+\.?\d*)/) {
        return $1;
    }
    return undef;
}

